import os
import shutil
from topopilot.api.api_classes import LLM
from topopilot.utils import randomness

_session_folder = "./.topopilot"
_llm = LLM.gpt54LowReasoning
_verifier_llm = LLM.gpt54LowReasoning
_checks_intention = True
_correctness_checks_on = True

def correctness_checks_on():
    return _correctness_checks_on

def _make_session_folder():
    if not os.path.isdir(session_folder()):
        os.mkdir(session_folder())

    cache_folder = os.path.join(session_folder(), "cache")
    if os.path.isdir(cache_folder):
        shutil.rmtree(cache_folder)
    os.mkdir(cache_folder)

def change_session_folder(folder):
    global _session_folder
    _session_folder = folder

    _make_session_folder()

def session_folder():
    return _session_folder

def get_random_seed():
    return randomness.get_seed()

def set_random_seed(seed : int):
    """Set the seed for TopoPilot-owned randomness only."""
    randomness.set_seed(seed)

def reset_randomness():
    randomness.reset()

def get_llm():
    return _llm

def set_llm(model : LLM):
    global _llm
    _llm = model

def get_verifier_llm():
    return _verifier_llm

def set_verifier_llm(model : LLM):
    global _verifier_llm
    _verifier_llm = model

def get_checks_intentions():
    return _checks_intention

def set_checks_intention(value):
    global _checks_intention
    _checks_intention = value

